INSERT INTO `pages` (`id`, `slug`, `title`, `eyebrow`, `heading`, `intro`, `body`, `footnote`, `image_ids`, `seo_title`, `seo_description`, `show_contact_form`, `is_active`, `created_at`, `updated_at`) VALUES (1,'shop','{\"en\":\"Shop\",\"ar\":\"المتجر\"}',NULL,NULL,'{\"en\":\"Every aisle in one place. Certified organic, harvested within 48 hours, delivered same day.\",\"ar\":\"كل الأقسام في مكان واحد. عضوي معتمد، يُحصد خلال 48 ساعة ويُوصَّل في اليوم نفسه.\"}','{\"en\":null}',NULL,NULL,NULL,NULL,0,0,'2026-10-04 09:12:36','2026-10-04 09:12:38'),
(2,'sale','{\"en\":\"Offers\",\"ar\":\"العروض\"}',NULL,NULL,'{\"en\":\"Every live discount, member deal and bundle, in one list. New offers land each Thursday.\",\"ar\":\"كل الخصومات والعروض والباقات الحالية في قائمة واحدة. عروض جديدة كل خميس.\"}','{\"en\":null}',NULL,NULL,NULL,NULL,0,0,'2026-10-04 09:12:36','2026-10-04 09:12:38'),
(3,'offers','{\"en\":\"Offers\",\"ar\":\"العروض\"}',NULL,NULL,'{\"en\":\"Every live discount, member deal and bundle, in one list. New offers land each Thursday.\",\"ar\":\"كل الخصومات والعروض والباقات الحالية في قائمة واحدة. عروض جديدة كل خميس.\"}','{\"en\":null}',NULL,NULL,NULL,NULL,0,1,'2026-10-04 09:12:36','2026-10-04 09:12:38'),
(4,'contact','{\"en\":\"Contact\",\"ar\":\"اتصل بنا\"}',NULL,NULL,'{\"en\":\"Questions about an order, a product or becoming a grower? Reach the team directly.\",\"ar\":\"لديك سؤال عن طلب أو منتج أو ترغب في أن تصبح مزارعاً معنا؟ تواصل مع الفريق مباشرة.\"}','{\"en\":null}',NULL,NULL,NULL,NULL,1,1,'2026-10-04 09:12:36','2026-10-04 09:12:38'),
(5,'faq','{\"en\":\"FAQs\",\"ar\":\"الأسئلة الشائعة\"}',NULL,NULL,'{\"en\":\"Answers to the questions we hear most about orders, delivery and our growers.\",\"ar\":\"إجابات عن أكثر الأسئلة شيوعاً حول الطلبات والتوصيل ومزارعينا.\"}','{\"en\":\"<h2>How fast is delivery?</h2><p>Most orders arrive within 45 minutes in San Francisco. You can also book a two-hour slot up to seven days ahead.</p><h2>Is everything certified organic?</h2><p>Yes. Every fresh product is certified organic and comes from a named grower within 80 miles of our depot.</p><h2>What does delivery cost?</h2><p>Delivery is free on orders over $50. Below that, a flat $4.99 fee applies.</p><h2>What if an item is damaged or missing?</h2><p>Report it in your account within 48 hours and we\'ll refund or replace it on your next order.</p><h2>Can I change my order after placing it?</h2><p>You can add or remove items until your order is packed, usually 30 minutes before the delivery slot.</p><h2>Do you take back packaging?</h2><p>Yes. Leave crates at the door on your next delivery and the driver will collect them.</p><h2>Which payment methods do you accept?</h2><p>Visa, Mastercard, American Express, Apple Pay, Google Pay and Daily Basket gift cards.</p><h2>How do I become a grower?</h2><p>Email growers@dailybasket.example with your farm details and certification. We visit every new supplier before listing their produce.</p>\",\"ar\":\"<h2>ما سرعة التوصيل؟</h2><p>تصل معظم الطلبات خلال 45 دقيقة في سان فرانسيسكو، ويمكنك أيضاً حجز موعد لمدة ساعتين حتى سبعة أيام مقدماً.</p><h2>هل كل المنتجات عضوية معتمدة؟</h2><p>نعم. كل منتج طازج عضوي معتمد ويأتي من مزارع معروف على بعد 80 ميلاً من مستودعنا.</p><h2>كم تكلفة التوصيل؟</h2><p>التوصيل مجاني للطلبات فوق 50$، وأقل من ذلك تُطبّق رسوم ثابتة 4.99$.</p><h2>ماذا لو كان منتج تالفاً أو ناقصاً؟</h2><p>أبلغ عنه من حسابك خلال 48 ساعة وسنعيد ثمنه أو نستبدله مع طلبك التالي.</p><h2>هل يمكنني تعديل طلبي بعد تقديمه؟</h2><p>يمكنك إضافة منتجات أو إزالتها حتى يتم تجهيز طلبك، عادةً قبل 30 دقيقة من موعد التوصيل.</p><h2>هل تستعيدون التغليف؟</h2><p>نعم. اترك الصناديق عند الباب في توصيلتك القادمة وسيجمعها السائق.</p><h2>ما طرق الدفع المقبولة؟</h2><p>فيزا وماستركارد وأمريكان إكسبريس وآبل باي وجوجل باي وبطاقات هدايا Daily Basket.</p><h2>كيف أصبح مزارعاً معكم؟</h2><p>راسل growers@dailybasket.example بتفاصيل مزرعتك واعتمادها. نزور كل مورّد جديد قبل عرض منتجاته.</p>\"}',NULL,NULL,NULL,NULL,0,1,'2026-10-04 09:12:36','2026-10-04 09:12:38'),
(6,'delivery-info','{\"en\":\"Delivery Info\",\"ar\":\"معلومات التوصيل\"}',NULL,NULL,'{\"en\":\"How, when and where we deliver, and what it costs.\",\"ar\":\"كيف ومتى وأين نوصّل، وكم يكلّف ذلك.\"}','{\"en\":\"<ul><li><strong>45 min</strong> Average delivery time</li><li><strong>$50</strong> Free delivery threshold</li><li><strong>7am–10pm</strong> Delivery hours, every day</li></ul><h2>Delivery areas</h2><p>We deliver across San Francisco, Oakland, Berkeley and San Jose. Enter your postcode at checkout to confirm coverage.</p><h2>Delivery slots</h2><p>Choose express delivery in 45 minutes or book a two-hour slot up to seven days ahead. Slots can be changed until your order is packed.</p><h2>Fees</h2><p>Delivery is free on orders over $50. Orders below $50 have a flat $4.99 fee. There is no minimum order.</p><h2>If you\'re not home</h2><p>Chilled items are packed in insulated liners and stay cold for four hours. Add safe-place instructions at checkout.</p>\",\"ar\":\"<ul><li><strong>45 دقيقة</strong> متوسط وقت التوصيل</li><li><strong>$50</strong> حد التوصيل المجاني</li><li><strong>7am–10pm</strong> ساعات التوصيل يومياً</li></ul><h2>مناطق التوصيل</h2><p>نوصّل في سان فرانسيسكو وأوكلاند وبيركلي وسان خوسيه. أدخل رمزك البريدي عند الدفع للتأكد من التغطية.</p><h2>مواعيد التوصيل</h2><p>اختر التوصيل السريع خلال 45 دقيقة أو احجز موعداً لمدة ساعتين حتى سبعة أيام مقدماً. يمكن تغيير الموعد حتى يتم تجهيز طلبك.</p><h2>الرسوم</h2><p>التوصيل مجاني للطلبات فوق 50$. الطلبات الأقل تُحتسب عليها رسوم ثابتة 4.99$. لا يوجد حد أدنى للطلب.</p><h2>إذا لم تكن في المنزل</h2><p>تُغلّف المنتجات المبرّدة بعوازل وتبقى باردة أربع ساعات. أضف تعليمات مكان آمن عند الدفع.</p>\"}',NULL,NULL,NULL,NULL,0,1,'2026-10-04 09:12:36','2026-10-04 09:12:38'),
(7,'returns-refunds','{\"en\":\"Returns & Refunds\",\"ar\":\"الإرجاع والاسترداد\"}',NULL,NULL,'{\"en\":\"If something isn\'t right, we\'ll replace it or refund you. No questions asked.\",\"ar\":\"إذا لم يكن شيء على ما يرام، نستبدله أو نعيد لك المبلغ دون أسئلة.\"}','{\"en\":\"<ul><li><strong>48 hrs</strong> To report an issue</li><li><strong>100%</strong> Refund on quality issues</li><li><strong>3–5 days</strong> Card refund time</li></ul><h2>Quality guarantee</h2><p>If any product isn\'t fresh or up to standard, we\'ll refund it in full. You don\'t need to send it back.</p><h2>How to request a refund</h2><p>Open My Orders, select the order and choose Report an issue. Add a photo if you can. Most requests are approved instantly.</p><h2>Refund methods</h2><p>Refunds go back to your original payment method in 3–5 working days, or instantly as Daily Basket credit.</p><h2>Missing items</h2><p>If an item is missing, we\'ll refund it or deliver it free on your next order, whichever you prefer.</p>\",\"ar\":\"<ul><li><strong>48 hrs</strong> للإبلاغ عن مشكلة</li><li><strong>100٪</strong> استرداد عند مشاكل الجودة</li><li><strong>3–5 days</strong> مدة استرداد البطاقة</li></ul><h2>ضمان الجودة</h2><p>إذا لم يكن أي منتج طازجاً أو بالمستوى المطلوب، نعيد لك ثمنه كاملاً دون الحاجة لإرجاعه.</p><h2>كيف تطلب استرداد المبلغ</h2><p>افتح طلباتي، اختر الطلب ثم «الإبلاغ عن مشكلة». أضف صورة إن أمكن. تُقبل معظم الطلبات فوراً.</p><h2>طرق الاسترداد</h2><p>يُعاد المبلغ إلى وسيلة الدفع الأصلية خلال 3–5 أيام عمل، أو فوراً كرصيد في Daily Basket.</p><h2>منتجات ناقصة</h2><p>إذا نقص منتج، نعيد ثمنه أو نوصّله مجاناً مع طلبك التالي، كما تفضّل.</p>\"}',NULL,NULL,NULL,NULL,0,1,'2026-10-04 09:12:36','2026-10-04 09:12:38'),
(8,'our-growers','{\"en\":\"Our Growers\",\"ar\":\"مزارعونا\"}',NULL,NULL,'{\"en\":\"Every product comes from a named farm within 80 miles of our depot.\",\"ar\":\"كل منتج يأتي من مزرعة معروفة على بعد 80 ميلاً من مستودعنا.\"}','{\"en\":\"<ul><li><strong>42</strong> Partner farms</li><li><strong>80 mi</strong> Maximum distance from depot</li><li><strong>48 hrs</strong> Field to door</li></ul><h2>How we choose growers</h2><p>Every farm is certified organic and visited by our sourcing team before we list their produce.</p><h2>Fair prices</h2><p>Growers set their own prices and are paid within seven days. We don\'t ask for listing fees or promotional contributions.</p>\",\"ar\":\"<ul><li><strong>42</strong> مزارع شريكة</li><li><strong>80 ميلاً</strong> أقصى مسافة من المستودع</li><li><strong>48 hrs</strong> من الحقل إلى الباب</li></ul><h2>كيف نختار المزارعين</h2><p>كل مزرعة عضوية معتمدة ويزورها فريق التوريد لدينا قبل عرض منتجاتها.</p><h2>أسعار عادلة</h2><p>يحدد المزارعون أسعارهم ويُدفع لهم خلال سبعة أيام. لا نطلب رسوم إدراج أو مساهمات ترويجية.</p>\"}',NULL,NULL,NULL,NULL,0,1,'2026-10-04 09:12:36','2026-10-04 09:12:38'),
(9,'sustainability','{\"en\":\"Sustainability\",\"ar\":\"الاستدامة\"}',NULL,NULL,'{\"en\":\"Plastic-free packaging, carbon-neutral routes and fair prices paid to growers.\",\"ar\":\"تغليف خالٍ من البلاستيك، ومسارات محايدة للكربون، وأسعار عادلة للمزارعين.\"}','{\"en\":\"<ul><li><strong>38 t</strong> Plastic avoided last year</li><li><strong>100%</strong> Electric delivery fleet</li><li><strong>0</strong> Food waste to landfill</li></ul><h2>Packaging</h2><p>Returnable crates and home-compostable liners replace single-use plastic across every order.</p><h2>Transport</h2><p>Our vans are fully electric and routes are planned to minimise miles. Remaining emissions are offset through verified projects.</p><h2>Food waste</h2><p>Unsold produce goes to local food banks each evening. Anything left is composted and returned to partner farms.</p><h2>Reporting</h2><p>We publish an impact report every year with our packaging, emissions and waste figures.</p>\",\"ar\":\"<ul><li><strong>38 t</strong> بلاستيك تجنبناه العام الماضي</li><li><strong>100٪</strong> أسطول توصيل كهربائي</li><li><strong>0</strong> هدر طعام إلى المكبّات</li></ul><h2>التغليف</h2><p>صناديق قابلة للإرجاع وبطانات قابلة للتحلل منزلياً بدلاً من البلاستيك أحادي الاستخدام في كل طلب.</p><h2>النقل</h2><p>سياراتنا كهربائية بالكامل والمسارات مخططة لتقليل المسافات، ونعوّض الانبعاثات المتبقية عبر مشاريع موثّقة.</p><h2>هدر الطعام</h2><p>تذهب المنتجات غير المباعة كل مساء إلى بنوك الطعام المحلية، وما يتبقى يتحول إلى سماد يعود للمزارع الشريكة.</p><h2>التقارير</h2><p>ننشر كل عام تقرير أثر يتضمن أرقام التغليف والانبعاثات والهدر.</p>\"}',NULL,NULL,NULL,NULL,0,1,'2026-10-04 09:12:36','2026-10-04 09:12:38'),
(10,'careers','{\"en\":\"Careers\",\"ar\":\"الوظائف\"}',NULL,NULL,'{\"en\":\"Join the team getting fresh food from local farms to local doors.\",\"ar\":\"انضم إلى الفريق الذي يوصل الطعام الطازج من المزارع المحلية إلى أبواب البيوت.\"}','{\"en\":\"<h2>Open roles</h2><ul><li><strong>Delivery Driver</strong> — Logistics · San Francisco · Full-time</li><li><strong>Warehouse Picker</strong> — Operations · San Francisco · Part-time</li><li><strong>Produce Buyer</strong> — Sourcing · San Francisco · Full-time</li><li><strong>Customer Support Specialist</strong> — Customer Care · Remote (US) · Full-time</li><li><strong>Senior Frontend Engineer</strong> — Technology · Hybrid, SF · Full-time</li></ul><p>To apply, email careers@dailybasket.example with the role in the subject line.</p>\",\"ar\":\"<h2>الوظائف المتاحة</h2><ul><li><strong>سائق توصيل</strong> — الخدمات اللوجستية · سان فرانسيسكو · دوام كامل</li><li><strong>مجهّز طلبات في المستودع</strong> — العمليات · سان فرانسيسكو · دوام جزئي</li><li><strong>مشترٍ للمنتجات الطازجة</strong> — التوريد · سان فرانسيسكو · دوام كامل</li><li><strong>أخصائي دعم العملاء</strong> — رعاية العملاء · عن بُعد (الولايات المتحدة) · دوام كامل</li><li><strong>مهندس واجهات أمامية أول</strong> — التقنية · هجين، سان فرانسيسكو · دوام كامل</li></ul><p>للتقديم، راسل careers@dailybasket.example واكتب اسم الوظيفة في عنوان الرسالة.</p>\"}',NULL,NULL,NULL,NULL,0,1,'2026-10-04 09:12:36','2026-10-04 09:12:38'),
(11,'privacy-policy','{\"en\":\"Privacy Policy\",\"ar\":\"سياسة الخصوصية\"}',NULL,NULL,'{\"en\":\"How Daily Basket collects, uses and protects your personal information. Last updated September 1, 2026.\",\"ar\":\"كيف تجمع Daily Basket معلوماتك الشخصية وتستخدمها وتحميها. آخر تحديث 1 سبتمبر 2026.\"}','{\"en\":\"<h2>Information we collect</h2><p>Your name, email, phone number, delivery addresses and order history. Payment details are handled by our payment provider and never stored on our servers.</p><h2>How we use it</h2><p>To process and deliver orders, provide customer support, send order updates and, if you opt in, share offers and harvest notes.</p><h2>Sharing</h2><p>We share only what is needed with delivery partners and payment processors. We never sell your personal data.</p><h2>Cookies</h2><p>We use essential cookies to keep you signed in and remember your basket, plus optional analytics cookies you can turn off in Settings.</p><h2>Data retention</h2><p>Order records are kept for seven years for tax purposes. Other account data is deleted within 30 days of closing your account.</p><h2>Your rights</h2><p>You can access, correct, export or delete your data at any time from your account, or by emailing privacy@dailybasket.example.</p><h2>Contact</h2><p>Daily Basket, 18 Meadow Row, San Francisco, CA 94110. Email privacy@dailybasket.example with any questions about this policy.</p>\",\"ar\":\"<h2>المعلومات التي نجمعها</h2><p>اسمك وبريدك الإلكتروني ورقم هاتفك وعناوين التوصيل وسجل الطلبات. تتولى جهة الدفع بيانات الدفع ولا تُحفظ على خوادمنا أبداً.</p><h2>كيف نستخدمها</h2><p>لمعالجة الطلبات وتوصيلها، وتقديم الدعم، وإرسال تحديثات الطلب، ومشاركة العروض ونشرات الحصاد إن اخترت ذلك.</p><h2>المشاركة</h2><p>نشارك فقط ما يلزم مع شركاء التوصيل ومعالجي الدفع. لا نبيع بياناتك الشخصية أبداً.</p><h2>ملفات تعريف الارتباط</h2><p>نستخدم ملفات أساسية لإبقائك مسجلاً وتذكّر سلتك، وملفات تحليلات اختيارية يمكنك إيقافها.</p><h2>الاحتفاظ بالبيانات</h2><p>تُحفظ سجلات الطلبات سبع سنوات لأغراض ضريبية. تُحذف بيانات الحساب الأخرى خلال 30 يوماً من إغلاقه.</p><h2>حقوقك</h2><p>يمكنك الاطلاع على بياناتك أو تصحيحها أو تصديرها أو حذفها في أي وقت من حسابك، أو بمراسلة privacy@dailybasket.example.</p><h2>التواصل</h2><p>Daily Basket، 18 ميدو رو، سان فرانسيسكو، كاليفورنيا 94110. راسل privacy@dailybasket.example لأي سؤال عن هذه السياسة.</p>\"}',NULL,NULL,NULL,NULL,0,1,'2026-10-04 09:12:36','2026-10-04 09:12:38'),
(12,'terms-conditions','{\"en\":\"Terms & Conditions\",\"ar\":\"الشروط والأحكام\"}',NULL,NULL,'{\"en\":\"The terms that apply when you use Daily Basket and place an order. Last updated September 1, 2026.\",\"ar\":\"الشروط التي تنطبق عند استخدامك Daily Basket وتقديم طلب. آخر تحديث 1 سبتمبر 2026.\"}','{\"en\":\"<h2>Using Daily Basket</h2><p>By creating an account or placing an order you agree to these terms. You must be 18 or older to place an order.</p><h2>Orders and pricing</h2><p>Prices include applicable taxes and are confirmed at checkout. Fresh items are priced by the listed weight and may vary slightly.</p><h2>Substitutions</h2><p>If an item is unavailable we may offer a similar substitute. You can reject any substitute at the door for a full refund.</p><h2>Delivery</h2><p>We aim to deliver within the chosen slot. If we are late by more than 30 minutes, your delivery fee is refunded automatically.</p><h2>Cancellations</h2><p>You can cancel free of charge until your order is packed. After that, cancellation may not be possible.</p><h2>Gift cards and promotions</h2><p>Gift cards are valid for 24 months and cannot be exchanged for cash. Promo codes cannot be combined unless stated.</p><h2>Liability</h2><p>Our liability is limited to the value of your order, except where the law does not allow this limitation.</p><h2>Changes to these terms</h2><p>We may update these terms. Significant changes will be emailed to you at least 14 days before they take effect.</p>\",\"ar\":\"<h2>استخدام Daily Basket</h2><p>بإنشاء حساب أو تقديم طلب فإنك توافق على هذه الشروط. يجب أن يكون عمرك 18 عاماً أو أكثر لتقديم طلب.</p><h2>الطلبات والأسعار</h2><p>تشمل الأسعار الضرائب المطبقة وتُؤكَّد عند الدفع. تُسعَّر المنتجات الطازجة حسب الوزن المعلن وقد تختلف قليلاً.</p><h2>البدائل</h2><p>إذا لم يتوفر منتج قد نعرض بديلاً مشابهاً، ويمكنك رفضه عند الباب واسترداد ثمنه كاملاً.</p><h2>التوصيل</h2><p>نسعى للتوصيل ضمن الموعد المختار. إذا تأخرنا أكثر من 30 دقيقة تُعاد رسوم التوصيل تلقائياً.</p><h2>الإلغاء</h2><p>يمكنك الإلغاء مجاناً حتى يتم تجهيز طلبك، وبعدها قد لا يكون الإلغاء ممكناً.</p><h2>بطاقات الهدايا والعروض</h2><p>بطاقات الهدايا صالحة 24 شهراً ولا تُستبدل نقداً. لا يمكن الجمع بين رموز الخصم ما لم يُذكر ذلك.</p><h2>المسؤولية</h2><p>تقتصر مسؤوليتنا على قيمة طلبك، إلا حيث لا يسمح القانون بذلك.</p><h2>تغييرات الشروط</h2><p>قد نحدّث هذه الشروط، وسنراسلك بالتغييرات المهمة قبل 14 يوماً على الأقل من سريانها.</p>\"}',NULL,NULL,NULL,NULL,0,1,'2026-10-04 09:12:36','2026-10-04 09:12:38');
