INSERT INTO `products` (`id`, `name`, `slug`, `short_description`, `description`, `dimensions`, `delivery_returns`, `trust_badges`, `status`, `is_featured`, `made_to_order`, `from_price`, `configuration`, `brand`, `brand_id`, `rating_average`, `rating_count`, `seo_title`, `seo_description`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES (1,'{\"en\":\"Organic Hass Avocado\",\"ar\":\"أفوكادو هاس عضوي\"}','organic-hass-avocado','{\"en\":\"<p>Picked ripe at Sunridge Orchards and in our cold room within hours. Sweet, fragrant and certified organic, with no wax coatings.</p>\",\"ar\":\"قُطفت ناضجة في بساتين صن ريدج ووصلت غرفة التبريد لدينا خلال ساعات. حلوة وعطرة وعضوية معتمدة، بلا طبقات شمعية.\"}','{\"en\":\"<p>Picked ripe at Sunridge Orchards and in our cold room within hours. Sweet, fragrant and certified organic, with no wax coatings. Every batch is traced back to the field or kitchen it came from, and the grower\'s name is printed on the label.</p><p>We buy direct and pay growers above market rate, which is why the price stays fair for you and the farm. Packed in compostable fibre and delivered on electric vans across the city.</p><h3>Storage &amp; use</h3><ul><li>Store at room temperature until ripe, then refrigerate.</li><li>Rinse just before eating, not before storing.</li><li>Best enjoyed within 4–5 days.</li></ul>\",\"ar\":\"<p>قُطفت ناضجة في بساتين صن ريدج ووصلت غرفة التبريد لدينا خلال ساعات. حلوة وعطرة وعضوية معتمدة، بلا طبقات شمعية. تُتتبَّع كل دفعة إلى الحقل أو المطبخ الذي جاءت منه، واسم المزارع مطبوع على الملصق.</p><p>نشتري مباشرة وندفع للمزارعين أكثر من سعر السوق، ولذلك يبقى السعر عادلاً لك وللمزرعة. نغلّف بألياف قابلة للتحلل ونوصّل بسيارات كهربائية في أنحاء المدينة.</p><h3>التخزين والاستخدام</h3><ul><li>احفظها في حرارة الغرفة حتى تنضج، ثم في الثلاجة.</li><li>اغسلها قبل الأكل مباشرة لا قبل التخزين.</li><li>الأفضل تناولها خلال 4–5 أيام.</li></ul>\"}','{\"en\":\"<p>Per 100 g</p><ul><li>Energy — 160 kcal</li><li>Carbohydrate — 9 g</li><li>of which sugars — 0.7 g</li><li>Fibre — 6.7 g</li><li>Protein — 2 g</li><li>Vitamin C — 10 mg</li></ul>\",\"ar\":\"<p>لكل 100 غ</p><ul><li>الطاقة — 160 kcal</li><li>الكربوهيدرات — 9 g</li><li>منها سكريات — 0.7 g</li><li>الألياف — 6.7 g</li><li>البروتين — 2 g</li><li>فيتامين C — 10 mg</li></ul>\"}',NULL,NULL,'active',0,0,0,NULL,'Sunridge Orchards',1,4.67,3,'[]','[]','2026-10-04 09:12:37','2026-10-04 09:12:37','2026-10-04 09:12:38',NULL),
(2,'{\"en\":\"Baby Leaf Spinach\",\"ar\":\"سبانخ أوراق صغيرة\"}','baby-leaf-spinach','{\"en\":\"<p>Pulled from the soil at Two Creeks Farm this morning. Crisp, full-flavoured and grown without synthetic pesticides.</p>\",\"ar\":\"قُلعت من تربة مزرعة تو كريكس هذا الصباح. مقرمشة وغنية بالنكهة، ومزروعة دون مبيدات صناعية.\"}','{\"en\":\"<p>Pulled from the soil at Two Creeks Farm this morning. Crisp, full-flavoured and grown without synthetic pesticides. Every batch is traced back to the field or kitchen it came from, and the grower\'s name is printed on the label.</p><p>We buy direct and pay growers above market rate, which is why the price stays fair for you and the farm. Packed in compostable fibre and delivered on electric vans across the city.</p><h3>Storage &amp; use</h3><ul><li>Keep refrigerated in the crisper drawer.</li><li>Wrap leafy greens in a damp cloth to keep them crisp.</li><li>Best used within 3–5 days.</li></ul>\",\"ar\":\"<p>قُلعت من تربة مزرعة تو كريكس هذا الصباح. مقرمشة وغنية بالنكهة، ومزروعة دون مبيدات صناعية. تُتتبَّع كل دفعة إلى الحقل أو المطبخ الذي جاءت منه، واسم المزارع مطبوع على الملصق.</p><p>نشتري مباشرة وندفع للمزارعين أكثر من سعر السوق، ولذلك يبقى السعر عادلاً لك وللمزرعة. نغلّف بألياف قابلة للتحلل ونوصّل بسيارات كهربائية في أنحاء المدينة.</p><h3>التخزين والاستخدام</h3><ul><li>احفظها مبرّدة في درج الخضار.</li><li>لفّ الورقيات بقطعة قماش رطبة لتبقى مقرمشة.</li><li>الأفضل استخدامها خلال 3–5 أيام.</li></ul>\"}','{\"en\":\"<p>Per 100 g</p><ul><li>Energy — 23 kcal</li><li>Carbohydrate — 3.6 g</li><li>of which sugars — 0.4 g</li><li>Fibre — 2.2 g</li><li>Protein — 2.9 g</li><li>Iron — 2.7 mg</li></ul>\",\"ar\":\"<p>لكل 100 غ</p><ul><li>الطاقة — 23 kcal</li><li>الكربوهيدرات — 3.6 g</li><li>منها سكريات — 0.4 g</li><li>الألياف — 2.2 g</li><li>البروتين — 2.9 g</li><li>الحديد — 2.7 mg</li></ul>\"}',NULL,NULL,'active',0,0,0,NULL,'Two Creeks Farm',2,4.67,3,'[]','[]','2026-10-04 09:12:37','2026-10-04 09:12:37','2026-10-04 09:12:38',NULL),
(3,'{\"en\":\"Free-Range Eggs\",\"ar\":\"بيض دجاج حر\"}','free-range-eggs','{\"en\":\"<p>From grass-fed herds at Hollow Creek Dairy. Gently pasteurised, never homogenised, bottled the day it is collected.</p>\",\"ar\":\"من قطعان تتغذى على العشب في ألبان هولو كريك. مبسترة بلطف وغير مجانسة، وتُعبّأ في يوم جمعها.\"}','{\"en\":\"<p>From grass-fed herds at Hollow Creek Dairy. Gently pasteurised, never homogenised, bottled the day it is collected. Every batch is traced back to the field or kitchen it came from, and the grower\'s name is printed on the label.</p><p>We buy direct and pay growers above market rate, which is why the price stays fair for you and the farm. Packed in compostable fibre and delivered on electric vans across the city.</p><h3>Storage &amp; use</h3><ul><li>Keep refrigerated at 1–4°C.</li><li>Use within 3 days of opening.</li><li>Shake gently before pouring; cream rises naturally.</li></ul>\",\"ar\":\"<p>من قطعان تتغذى على العشب في ألبان هولو كريك. مبسترة بلطف وغير مجانسة، وتُعبّأ في يوم جمعها. تُتتبَّع كل دفعة إلى الحقل أو المطبخ الذي جاءت منه، واسم المزارع مطبوع على الملصق.</p><p>نشتري مباشرة وندفع للمزارعين أكثر من سعر السوق، ولذلك يبقى السعر عادلاً لك وللمزرعة. نغلّف بألياف قابلة للتحلل ونوصّل بسيارات كهربائية في أنحاء المدينة.</p><h3>التخزين والاستخدام</h3><ul><li>احفظها مبرّدة بين 1–4°م.</li><li>استخدمها خلال 3 أيام من فتحها.</li><li>رجّها بلطف قبل السكب؛ فالقشدة تطفو طبيعياً.</li></ul>\"}','{\"en\":\"<p>Per 100 g</p><ul><li>Energy — 64 kcal</li><li>Fat — 3.6 g</li><li>of which saturates — 2.3 g</li><li>Carbohydrate — 4.8 g</li><li>Protein — 3.4 g</li><li>Calcium — 120 mg</li></ul>\",\"ar\":\"<p>لكل 100 غ</p><ul><li>الطاقة — 64 kcal</li><li>الدهون — 3.6 g</li><li>منها دهون مشبعة — 2.3 g</li><li>الكربوهيدرات — 4.8 g</li><li>البروتين — 3.4 g</li><li>الكالسيوم — 120 mg</li></ul>\"}',NULL,NULL,'active',0,0,0,NULL,'Hollow Creek Dairy',3,4.67,3,'[]','[]','2026-10-04 09:12:37','2026-10-04 09:12:37','2026-10-04 09:12:38',NULL),
(4,'{\"en\":\"Sourdough Country Loaf\",\"ar\":\"رغيف عجين مخمّر ريفي\"}','sourdough-country-loaf','{\"en\":\"<p>Slow-proved overnight at Mill Lane Bakehouse using stone-milled organic flour, sea salt and nothing else you cannot pronounce.</p>\",\"ar\":\"مختمرة ببطء طوال الليل في مخبز ميل لين من دقيق عضوي مطحون بالحجر وملح البحر فقط.\"}','{\"en\":\"<p>Slow-proved overnight at Mill Lane Bakehouse using stone-milled organic flour, sea salt and nothing else you cannot pronounce. Every batch is traced back to the field or kitchen it came from, and the grower\'s name is printed on the label.</p><p>We buy direct and pay growers above market rate, which is why the price stays fair for you and the farm. Packed in compostable fibre and delivered on electric vans across the city.</p><h3>Storage &amp; use</h3><ul><li>Store in a paper bag at room temperature.</li><li>Refresh in a hot oven for 5 minutes.</li><li>Slice and freeze for up to 1 month.</li></ul>\",\"ar\":\"<p>مختمرة ببطء طوال الليل في مخبز ميل لين من دقيق عضوي مطحون بالحجر وملح البحر فقط. تُتتبَّع كل دفعة إلى الحقل أو المطبخ الذي جاءت منه، واسم المزارع مطبوع على الملصق.</p><p>نشتري مباشرة وندفع للمزارعين أكثر من سعر السوق، ولذلك يبقى السعر عادلاً لك وللمزرعة. نغلّف بألياف قابلة للتحلل ونوصّل بسيارات كهربائية في أنحاء المدينة.</p><h3>التخزين والاستخدام</h3><ul><li>احفظه في كيس ورقي بحرارة الغرفة.</li><li>أعد تحميصه 5 دقائق على 180°م لقشرة مقرمشة.</li><li>جمّد الشرائح حتى شهر واحد.</li></ul>\"}','{\"en\":\"<p>Per 100 g</p><ul><li>Energy — 250 kcal</li><li>Fat — 1.2 g</li><li>Carbohydrate — 49 g</li><li>of which sugars — 2.1 g</li><li>Fibre — 3.4 g</li><li>Protein — 9 g</li></ul>\",\"ar\":\"<p>لكل 100 غ</p><ul><li>الطاقة — 250 kcal</li><li>الدهون — 1.2 g</li><li>الكربوهيدرات — 49 g</li><li>منها سكريات — 2.1 g</li><li>الألياف — 3.4 g</li><li>البروتين — 9 g</li></ul>\"}',NULL,NULL,'active',0,0,0,NULL,'Mill Lane Bakehouse',4,4.67,3,'[]','[]','2026-10-04 09:12:37','2026-10-04 09:12:37','2026-10-04 09:12:38',NULL),
